/**
 * Generates the WAV fixtures Chromium replays as a fake microphone
 * (--use-file-for-fake-audio-capture). Deterministic, so the committed files
 * can be regenerated byte-identically:
 *
 *   node apps/web/e2e/fixtures/generate.mjs
 */
import { writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = dirname(fileURLToPath(import.meta.url));

const SAMPLE_RATE = 44100;
const SECONDS = 6;
const A4 = 440;

/** Equal-temperament frequency for a MIDI note. */
const freq = (midi) => A4 * Math.pow(2, (midi - 69) / 12);
/** Detune by cents. */
const detune = (hz, cents) => hz * Math.pow(2, cents / 1200);

/**
 * A plucked-string-ish tone: a few harmonics, mild decay, looping cleanly so
 * Chromium can repeat the file without a click at the seam.
 */
function tone(frequency, seconds = SECONDS) {
  const length = Math.floor(SAMPLE_RATE * seconds);
  const out = new Float32Array(length);
  const weights = [1, 0.5, 0.32, 0.18, 0.1];

  weights.forEach((weight, index) => {
    const harmonic = (index + 1) * frequency;
    if (harmonic >= SAMPLE_RATE / 2) return;
    const step = (2 * Math.PI * harmonic) / SAMPLE_RATE;
    for (let i = 0; i < length; i += 1) out[i] += weight * Math.sin(step * i);
  });

  let peak = 0;
  for (let i = 0; i < length; i += 1) peak = Math.max(peak, Math.abs(out[i]));
  for (let i = 0; i < length; i += 1) out[i] = (out[i] / peak) * 0.7;
  return out;
}

/** Linear-in-pitch sweep, for the User Story 2 retune spec. */
function sweep(fromHz, toHz, seconds = SECONDS) {
  const length = Math.floor(SAMPLE_RATE * seconds);
  const out = new Float32Array(length);
  let phase = 0;
  for (let i = 0; i < length; i += 1) {
    const t = i / (length - 1);
    const f = fromHz * Math.pow(toHz / fromHz, t);
    phase += (2 * Math.PI * f) / SAMPLE_RATE;
    out[i] = 0.7 * Math.sin(phase);
  }
  return out;
}

function writeWav(name, samples) {
  const dataLength = samples.length * 2;
  const buffer = Buffer.alloc(44 + dataLength);

  buffer.write('RIFF', 0);
  buffer.writeUInt32LE(36 + dataLength, 4);
  buffer.write('WAVE', 8);
  buffer.write('fmt ', 12);
  buffer.writeUInt32LE(16, 16); // PCM chunk size
  buffer.writeUInt16LE(1, 20); // PCM
  buffer.writeUInt16LE(1, 22); // mono
  buffer.writeUInt32LE(SAMPLE_RATE, 24);
  buffer.writeUInt32LE(SAMPLE_RATE * 2, 28); // byte rate
  buffer.writeUInt16LE(2, 32); // block align
  buffer.writeUInt16LE(16, 34); // bits per sample
  buffer.write('data', 36);
  buffer.writeUInt32LE(dataLength, 40);

  for (let i = 0; i < samples.length; i += 1) {
    const clamped = Math.max(-1, Math.min(1, samples[i]));
    buffer.writeInt16LE(Math.round(clamped * 32767), 44 + i * 2);
  }

  writeFileSync(join(HERE, name), buffer);
  console.log(`wrote ${name} (${(buffer.length / 1024).toFixed(0)} KB)`);
}

const e2 = freq(40); // 82.41 Hz, guitar low E
writeWav('e2-in-tune.wav', tone(e2));
writeWav('e2-flat-20.wav', tone(detune(e2, -20)));
writeWav('e2-sharp-20.wav', tone(detune(e2, 20)));
writeWav('e2-to-d2-sweep.wav', sweep(e2, freq(38)));
